	"project1/view/View1.view.xml":'<mvc:View\n    controllerName="project1.controller.View1"\n    xmlns="sap.m"\n    xmlns:mvc="sap.ui.core.mvc"\n    xmlns:tnt="sap.tnt"\n    xmlns:f="sap.f"\n    xmlns:core="sap.ui.core"\n    height="100%"\n><HBox\n        id="mainLayout"\n        width="100%"\n        height="100%"\n        renderType="Bare"\n    ><VBox\n            id="sideContainer"\n            width="70px"\n            height="100%"\n            renderType="Bare"\n            class="sideContainer"\n        ><Button\n                icon="sap-icon://navigation-right-arrow"\n                press=".onCollapseExpandPress"\n            /><tnt:SideNavigation\n                id="sideNavigation"\n                selectedKey="dashboard"\n                expanded="false"\n            ><tnt:NavigationList id="navigationList"><tnt:NavigationListItem\n                        key="dashboard"\n                        text="Dashboard"\n                        icon="sap-icon://home"\n                        select=".onNavigationSelect"\n                    /><tnt:NavigationListItem\n                        key="Vendor"\n                        text="Vendors"\n                        icon="sap-icon://supplier"\n                        select=".onNavigationSelect"\n                    /><tnt:NavigationListItem\n                        key="purchaseOrders"\n                        text="Purchase Orders"\n                        icon="sap-icon://cart"\n                        select=".onNavigationSelect"\n                    /><tnt:NavigationListItem\n                        key="invoices"\n                        text="Invoices"\n                        icon="sap-icon://receipt"\n                        select=".onNavigationSelect"\n                    /></tnt:NavigationList></tnt:SideNavigation></VBox><Page\n            id="mainPage"\n            width="auto"\n            showHeader="false"\n            class="sapUiNoContentPadding"\n        ><content><f:DynamicPage\n                    id="dashboardPage"\n                    fitContent="true"\n                ><f:title><f:DynamicPageTitle><f:heading><Title text="Procurement Overview" /></f:heading></f:DynamicPageTitle></f:title><f:content><VBox\n                            width="100%"\n                            class="sapUiResponsiveContentPadding"\n                        ><HBox\n                                width="100%"\n                                wrap="Wrap"\n                                renderType="Bare"\n                                class="sapUiSmallMarginBottom"\n                            ><GenericTile\n                                    id="vendorTile"\n                                    header="Total Vendors"\n                                    press=".onVendorPress"\n                                    class="sapUiSmallMarginEnd sapUiSmallMarginBottom"\n                                    width="300px"\n                                ><TileContent><NumericContent\n                                            id="vendorCount"\n                                            value="0"\n                                            icon="sap-icon://supplier"\n                                            valueColor="Good"\n                                        /></TileContent></GenericTile><GenericTile\n                                    id="poTile"\n                                    header="Purchase Orders"\n                                    press=".onPurchaseOrderPress"\n                                    class="sapUiSmallMarginEnd sapUiSmallMarginBottom"\n                                    width="300px"\n                                ><TileContent><NumericContent\n                                            id="poCount"\n                                            value="0"\n                                            icon="sap-icon://cart"\n                                            valueColor="Neutral"\n                                        /></TileContent></GenericTile><GenericTile\n                                    id="invoiceTile"\n                                    header="Total Invoices"\n                                    press=".onInvoicePress"\n                                    class="sapUiSmallMarginBottom"\n                                    width="300px"\n                                ><TileContent><NumericContent\n                                            id="invoiceCount"\n                                            value="0"\n                                            icon="sap-icon://receipt"\n                                            valueColor="Neutral"\n                                        /></TileContent></GenericTile></HBox></VBox></f:content></f:DynamicPage></content></Page></HBox></mvc:View>\n'
